package com.primehr.rsp.evaluation.application;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import com.primehr.config.PrimeHrProperties;import com.primehr.rsp.applicant.domain.PositionApplication;import com.primehr.rsp.applicant.storage.DocumentStorage;import com.primehr.rsp.evaluation.api.EvaluationExecutionDtos.*;import com.primehr.rsp.evaluation.domain.*;import com.primehr.rsp.evaluation.infrastructure.*;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import java.util.stream.Collectors;
@Service @Transactional public class EvaluationExecutionServiceImpl implements EvaluationExecutionService{
 private final EvaluationProceedingRepository proceedings;private final EvaluationCandidateRepository candidates;private final EvaluationStageRepository stages;private final EvaluationCriterionRepository criteria;private final CommitteeMemberRepository members;private final EvaluationSessionRepository sessions;private final EvaluationSessionCandidateRepository sessionCandidates;private final EvaluationAssignmentRepository assignments;private final ConflictDeclarationRepository conflicts;private final StageResultRepository results;private final PanelRatingRepository ratings;private final PanelRatingItemRepository ratingItems;private final ReferenceCheckRepository references;private final EvaluationEvidenceRepository evidence;private final HrmpsbMeetingRepository meetings;private final HrmpsbAttendanceRepository attendance;private final HrmpsbResolutionRepository resolutions;private final ComparativeEvaluationRepository comparisons;private final ComparativeEvaluationItemRepository comparisonItems;private final DocumentStorage storage;private final PrimeHrProperties properties;private final PrimeHrAuditService audit;private final ObjectMapper json;
 public EvaluationExecutionServiceImpl(EvaluationProceedingRepository p,EvaluationCandidateRepository c,EvaluationStageRepository s,EvaluationCriterionRepository cr,CommitteeMemberRepository m,EvaluationSessionRepository se,EvaluationSessionCandidateRepository sc,EvaluationAssignmentRepository a,ConflictDeclarationRepository co,StageResultRepository sr,PanelRatingRepository pr,PanelRatingItemRepository pi,ReferenceCheckRepository rc,EvaluationEvidenceRepository ee,HrmpsbMeetingRepository hm,HrmpsbAttendanceRepository ha,HrmpsbResolutionRepository hr,ComparativeEvaluationRepository ce,ComparativeEvaluationItemRepository ci,DocumentStorage ds,PrimeHrProperties pp,PrimeHrAuditService au,ObjectMapper j){proceedings=p;candidates=c;stages=s;criteria=cr;members=m;sessions=se;sessionCandidates=sc;assignments=a;conflicts=co;results=sr;ratings=pr;ratingItems=pi;references=rc;evidence=ee;meetings=hm;attendance=ha;resolutions=hr;comparisons=ce;comparisonItems=ci;storage=ds;properties=pp;audit=au;json=j;}

 @Override @Transactional(readOnly=true)public ExecutionOverview overview(String agency,String proceedingId,String actor){EvaluationProceeding p=proceeding(agency,proceedingId);requireCommitteeMember(p,actor);List<RatingResponse> visibleRatings=ratings.findByAgencyIdAndProceedingId(agency,proceedingId).stream().filter(value->value.getStatus()==PanelRating.Status.SUBMITTED||value.getRaterEmployeeNo().equalsIgnoreCase(actor)).map(this::response).toList();List<HrmpsbMeeting> meetingValues=meetings.findByAgencyIdAndProceedingIdOrderByMeetingRevisionAsc(agency,proceedingId);Set<String> meetingIds=meetingValues.stream().map(HrmpsbMeeting::getId).collect(Collectors.toSet());return new ExecutionOverview(proceedingId,p.getVersion(),sessions.findByAgencyIdAndProceedingIdOrderByStartsAtAsc(agency,proceedingId).stream().map(this::response).toList(),assignments.findByAgencyIdAndProceedingIdAndActiveTrue(agency,proceedingId).stream().map(this::response).toList(),conflicts.findByAgencyIdAndProceedingId(agency,proceedingId).stream().map(this::response).toList(),results.findByAgencyIdAndProceedingId(agency,proceedingId).stream().map(this::response).toList(),visibleRatings,references.findByAgencyIdAndProceedingId(agency,proceedingId).stream().map(this::response).toList(),meetingValues.stream().map(this::response).toList(),meetingValues.stream().flatMap(value->attendance.findByAgencyIdAndMeetingId(agency,value.getId()).stream()).map(value->new MeetingAttendanceResponse(value.getId(),value.getMeetingId(),value.getEmployeeNo(),value.getMemberRole(),value.getStatus().name(),value.isVotingEligible(),value.getVersion())).toList(),meetingIds.stream().flatMap(id->resolutions.findByAgencyIdAndMeetingId(agency,id).stream()).map(value->new ResolutionResponse(value.getId(),value.getMeetingId(),value.getCandidateId(),value.getRecommendation().name(),value.getReason(),value.getMethod().name(),value.getVotesFor(),value.getVotesAgainst(),value.getAbstentions(),value.getVersion())).toList(),comparisons.findByAgencyIdAndProceedingIdOrderByEvaluationRevisionAsc(agency,proceedingId).stream().map(this::response).toList(),evidence.findByAgencyIdAndProceedingId(agency,proceedingId).stream().map(EvaluationExecutionServiceImpl::response).toList());}

 @Override public SessionResponse createSession(String agency,String proceedingId,SessionInput r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,proceedingId);requireCoordinator(p,actor);requireExecutionState(p);EvaluationStage stage=stage(p,r.stageId());int revision=Math.toIntExact(sessions.countByAgencyIdAndProceedingIdAndStageId(agency,p.getId(),stage.getId())+1);EvaluationSession value=sessions.saveAndFlush(new EvaluationSession(agency,p.getId(),stage.getId(),revision,r.startsAt(),r.endsAt(),r.timeZone(),r.deliveryMode(),r.venue(),r.instructions(),r.capacity(),r.responsibleEmployeeNo()));for(String id:new LinkedHashSet<>(r.candidateIds())){EvaluationCandidate candidate=candidate(agency,p,id);requireActive(candidate);EvaluationSessionCandidate link=new EvaluationSessionCandidate(agency,value.getId(),candidate.getId());link.invite(Instant.now());sessionCandidates.save(link);}p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"CREATE_EVALUATION_SESSION","RSP_EVALUATION_SESSION",value.getId(),revision,value.getVersion(),null,response(value),null,correlation);return response(value);}
 @Override public SessionResponse updateSession(String agency,String id,SessionInput r,String actor,String correlation){EvaluationSession value=session(agency,id);EvaluationProceeding p=proceeding(agency,value.getProceedingId());requireCoordinator(p,actor);version(value.getVersion(),r.recordVersion());if(!value.getStageId().equals(r.stageId()))throw new ApplicationConflictException("A session stage is immutable");value.update(r.startsAt(),r.endsAt(),r.timeZone(),r.deliveryMode(),r.venue(),r.instructions(),r.capacity(),r.responsibleEmployeeNo(),r.changeReason());for(String candidateId:new LinkedHashSet<>(r.candidateIds()))if(sessionCandidates.findByAgencyIdAndSessionIdAndCandidateId(agency,id,candidateId).isEmpty()){requireActive(candidate(agency,p,candidateId));EvaluationSessionCandidate link=new EvaluationSessionCandidate(agency,id,candidateId);link.invite(Instant.now());sessionCandidates.save(link);}value=sessions.saveAndFlush(value);p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"UPDATE_EVALUATION_SESSION","RSP_EVALUATION_SESSION",id,value.getSessionRevision(),value.getVersion(),null,response(value),r.changeReason(),correlation);return response(value);}
 @Override public SessionResponse transitionSession(String agency,String id,Transition r,String actor,String action,String correlation){EvaluationSession value=session(agency,id);EvaluationProceeding p=proceeding(agency,value.getProceedingId());requireCoordinator(p,actor);version(value.getVersion(),r.recordVersion());switch(action){case"schedule"->value.schedule(actor,Instant.now());case"complete"->{if(sessionCandidates.findByAgencyIdAndSessionId(agency,id).stream().anyMatch(c->c.getAttendanceStatus()==EvaluationSessionCandidate.Attendance.PENDING))throw new ApplicationConflictException("Every candidate attendance must be recorded before completion");value.complete(actor,Instant.now());if(p.getStatus()==EvaluationProceeding.Status.OPEN)p.beginAssessment();}case"cancel"->value.cancel(actor,r.reason(),Instant.now());default->throw new IllegalArgumentException("Session action is invalid");}value=sessions.saveAndFlush(value);p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,action.toUpperCase(Locale.ROOT)+"_EVALUATION_SESSION","RSP_EVALUATION_SESSION",id,value.getSessionRevision(),value.getVersion(),null,response(value),r.reason(),correlation);return response(value);}
 @Override public SessionResponse attendance(String agency,String sessionId,String candidateId,AttendanceInput r,String actor,String correlation){EvaluationSession session=session(agency,sessionId);EvaluationProceeding p=proceeding(agency,session.getProceedingId());requireCoordinator(p,actor);if(session.getStatus()!=EvaluationSession.Status.SCHEDULED)throw new ApplicationConflictException("Attendance is recorded only for a SCHEDULED session");EvaluationSessionCandidate value=sessionCandidates.findByAgencyIdAndSessionIdAndCandidateId(agency,sessionId,candidateId).orElseThrow(()->new ResourceNotFoundException("Session candidate was not found"));version(value.getVersion(),r.recordVersion());value.attendance(r.status(),actor,r.reason(),Instant.now());sessionCandidates.saveAndFlush(value);p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"RECORD_EVALUATION_ATTENDANCE","RSP_EVALUATION_SESSION",sessionId,session.getSessionRevision(),value.getVersion(),null,Map.of("candidateId",candidateId,"attendance",r.status().name()),r.reason(),correlation);return response(session);}

 @Override public ProceedingExecutionResponse assignments(String agency,String proceedingId,Assignments r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,proceedingId);requireCoordinator(p,actor);version(p.getVersion(),r.proceedingRecordVersion());requireExecutionState(p);List<EvaluationAssignment> current=assignments.findByAgencyIdAndProceedingIdAndActiveTrue(agency,proceedingId);for(EvaluationAssignment old:current)old.deactivate(actor,Objects.requireNonNullElse(r.replacementReason(),"Assignment set replaced"),Instant.now());assignments.saveAll(current);Set<String> uniqueness=new HashSet<>();List<EvaluationAssignment> created=new ArrayList<>();for(AssignmentInput input:r.assignments()){EvaluationStage stage=input.stageId()==null?null:stage(p,input.stageId());EvaluationCandidate candidate=input.candidateId()==null?null:candidate(agency,p,input.candidateId());CommitteeMember member=requireCommitteeMember(p,input.employeeNo());validateAssignmentRole(member,input);String key=(input.stageId()+":"+input.candidateId()+":"+input.employeeNo()+":"+input.role()).toUpperCase(Locale.ROOT);if(!uniqueness.add(key))throw new IllegalArgumentException("Duplicate active assignment");if((input.role()==EvaluationAssignment.Role.EXAMINER&&hasRole(r.assignments(),input,EvaluationAssignment.Role.VALIDATOR))||(input.role()==EvaluationAssignment.Role.VALIDATOR&&hasRole(r.assignments(),input,EvaluationAssignment.Role.EXAMINER)))throw new ApplicationConflictException("The same employee cannot record and validate the same stage result");created.add(new EvaluationAssignment(agency,p.getId(),stage==null?null:stage.getId(),candidate==null?null:candidate.getId(),input.employeeNo(),input.role(),input.alternateForEmployeeNo(),actor,Instant.now()));}assignments.saveAll(created);p.executionChanged();p=proceedings.saveAndFlush(p);audit.record(agency,"REPLACE_EVALUATION_ASSIGNMENTS","RSP_EVALUATION_PROCEEDING",p.getId(),null,p.getVersion(),null,Map.of("assignmentCount",created.size()),r.replacementReason(),correlation);return new ProceedingExecutionResponse(p.getId(),p.getVersion(),assignments.findByAgencyIdAndProceedingIdAndActiveTrue(agency,p.getId()).stream().map(this::response).toList());}
 @Override public ConflictResponse declareConflict(String agency,String proceedingId,ConflictInput r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,proceedingId);version(p.getVersion(),r.proceedingRecordVersion());requireCommitteeMember(p,actor);EvaluationCandidate candidate=candidate(agency,p,r.candidateId());if(conflicts.findByAgencyIdAndProceedingIdAndCandidateIdAndEmployeeNoIgnoreCase(agency,p.getId(),candidate.getId(),actor).isPresent())throw new ApplicationConflictException("A conflict declaration already exists for this candidate");ConflictDeclaration value=conflicts.saveAndFlush(new ConflictDeclaration(agency,p.getId(),candidate.getId(),actor,r.outcome(),r.declaration(),Instant.now()));p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"DECLARE_EVALUATION_CONFLICT","RSP_CONFLICT_DECLARATION",value.getId(),null,value.getVersion(),null,response(value),r.declaration(),correlation);return response(value);}
 @Override public ConflictResponse resolveConflict(String agency,String id,ResolveConflict r,String actor,String correlation){ConflictDeclaration value=conflicts.findById(id).filter(v->v.getAgencyId().equals(agency)).orElseThrow(()->new ResourceNotFoundException("Conflict declaration was not found"));EvaluationProceeding p=proceeding(agency,value.getProceedingId());requireCoordinator(p,actor);version(value.getVersion(),r.recordVersion());value.resolve(r.resolution(),actor,r.reason(),Instant.now());value=conflicts.saveAndFlush(value);p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"RESOLVE_EVALUATION_CONFLICT","RSP_CONFLICT_DECLARATION",id,null,value.getVersion(),null,response(value),r.reason(),correlation);return response(value);}

 @Override public StageResultResponse recordResult(String agency,String proceedingId,StageResultInput r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,proceedingId);requireAssigned(p,r.stageId(),actor,EvaluationAssignment.Role.EXAMINER);EvaluationCandidate candidate=candidate(agency,p,r.candidateId());requireClearance(p,candidate,actor);EvaluationStage stage=stage(p,r.stageId());EvaluationSession session=session(agency,r.sessionId());if(!session.getProceedingId().equals(p.getId())||!session.getStageId().equals(stage.getId()))throw new ApplicationConflictException("Session does not belong to the proceeding stage");EvaluationSessionCandidate link=sessionCandidates.findByAgencyIdAndSessionIdAndCandidateId(agency,session.getId(),candidate.getId()).orElseThrow(()->new ApplicationConflictException("Candidate is not assigned to the session"));if(link.getAttendanceStatus()!=EvaluationSessionCandidate.Attendance.ATTENDED)throw new ApplicationConflictException("Only an attended candidate may receive a result");StageResult value=results.findByAgencyIdAndProceedingIdAndCandidateIdAndStageIdAndCurrentResultKeyIsNotNull(agency,p.getId(),candidate.getId(),stage.getId()).orElse(null);if(value==null){int revision=Math.toIntExact(results.countByAgencyIdAndProceedingIdAndCandidateIdAndStageId(agency,p.getId(),candidate.getId(),stage.getId())+1);value=new StageResult(agency,p.getId(),session.getId(),candidate.getId(),stage.getId(),revision,null,stage.isRequiresEvidence(),actor);}else{version(value.getVersion(),r.recordVersion());if(!value.getRecordedBy().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the assigned recorder may edit this result");}if(stage.getMode()==EvaluationStage.Mode.SCORED)value.recordScore(r.rawScore(),stage.getMaximumScore(),p.getBinding().getPolicy().getRoundingScale(),rounding(p),r.remarks());else value.recordGate(r.gateOutcome(),r.remarks());value=results.saveAndFlush(value);startAssessment(p);audit.record(agency,"RECORD_STAGE_RESULT","RSP_STAGE_RESULT",value.getId(),value.getResultRevision(),value.getVersion(),null,response(value),r.remarks(),correlation);return response(value);}
 @Override public StageResultResponse transitionResult(String agency,String id,Transition r,String actor,String action,String correlation){StageResult value=result(agency,id);EvaluationProceeding p=proceeding(agency,value.getProceedingId());version(value.getVersion(),r.recordVersion());switch(action){case"submit"->{requireAssigned(p,value.getStageId(),actor,EvaluationAssignment.Role.EXAMINER);requireClearance(p,candidate(agency,p,value.getCandidateId()),actor);if(value.isEvidenceRequired()&&!evidence.existsByAgencyIdAndOwnerTypeAndOwnerId(agency,EvaluationEvidence.OwnerType.STAGE_RESULT,id))throw new ApplicationConflictException("Required result evidence is missing");value.submit(actor,Instant.now());}case"validate"->{requireAssigned(p,value.getStageId(),actor,EvaluationAssignment.Role.VALIDATOR);requireClearance(p,candidate(agency,p,value.getCandidateId()),actor);value.validate(actor,Instant.now());}case"return"->{requireAssigned(p,value.getStageId(),actor,EvaluationAssignment.Role.VALIDATOR);value.returnForCorrection(actor,r.reason(),Instant.now());}default->throw new IllegalArgumentException("Result action is invalid");}value=results.saveAndFlush(value);p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,action.toUpperCase(Locale.ROOT)+"_STAGE_RESULT","RSP_STAGE_RESULT",id,value.getResultRevision(),value.getVersion(),null,response(value),r.reason(),correlation);return response(value);}

 @Override public RatingResponse recordRating(String agency,String proceedingId,RatingInput r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,proceedingId);requireAssigned(p,r.stageId(),actor,EvaluationAssignment.Role.PANEL_MEMBER);EvaluationCandidate candidate=candidate(agency,p,r.candidateId());requireClearance(p,candidate,actor);EvaluationStage stage=stage(p,r.stageId());if(stage.getType()!=EvaluationStage.Type.COMPETENCY_BASED_INTERVIEW&&stage.getType()!=EvaluationStage.Type.BEHAVIORAL_EVENT_INTERVIEW)throw new ApplicationConflictException("Panel ratings are limited to configured interview stages");PanelRating value=ratings.findByAgencyIdAndProceedingIdAndCandidateIdAndStageIdAndRaterEmployeeNoIgnoreCaseAndCurrentRatingKeyIsNotNull(agency,p.getId(),candidate.getId(),stage.getId(),actor).orElse(null);if(value==null){int revision=Math.toIntExact(ratings.countByAgencyIdAndProceedingIdAndCandidateIdAndStageIdAndRaterEmployeeNoIgnoreCase(agency,p.getId(),candidate.getId(),stage.getId(),actor)+1);value=ratings.saveAndFlush(new PanelRating(agency,p.getId(),candidate.getId(),stage.getId(),actor,revision,null));}else version(value.getVersion(),r.recordVersion());Map<String,EvaluationCriterion> configured=criteria.findByAgencyIdAndStageIdOrderByDisplayOrderAsc(agency,stage.getId()).stream().collect(Collectors.toMap(EvaluationCriterion::getId,c->c));if(r.items().size()!=configured.size()||r.items().stream().map(RatingItemInput::criterionId).distinct().count()!=configured.size())throw new ApplicationConflictException("Every configured criterion must be rated exactly once");ratingItems.deleteByAgencyIdAndRatingId(agency,value.getId());List<PanelRatingItem> items=new ArrayList<>();for(RatingItemInput input:r.items()){EvaluationCriterion criterion=configured.get(input.criterionId());if(criterion==null)throw new ApplicationConflictException("Rating criterion does not belong to the stage");if(input.maximumScore().compareTo(criterion.getMaximumScore())!=0)throw new ApplicationConflictException("Criterion maximum score does not match the published policy");if(criterion.isRequiresRemarks()&&(input.remarks()==null||input.remarks().isBlank()))throw new ApplicationConflictException("Required criterion remarks are missing");items.add(new PanelRatingItem(agency,value.getId(),criterion.getId(),input.rawScore(),criterion.getMaximumScore(),criterion.getWeight(),p.getBinding().getPolicy().getRoundingScale(),rounding(p),input.remarks()));}ratingItems.saveAll(items);BigDecimal total=items.stream().map(PanelRatingItem::getWeightedScore).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(p.getBinding().getPolicy().getRoundingScale(),rounding(p));value.calculate(total,r.overallRemarks());value=ratings.saveAndFlush(value);startAssessment(p);audit.record(agency,"RECORD_PANEL_RATING","RSP_PANEL_RATING",value.getId(),value.getRatingRevision(),value.getVersion(),null,response(value),r.overallRemarks(),correlation);return response(value);}
 @Override public RatingResponse transitionRating(String agency,String id,Transition r,String actor,String action,String correlation){PanelRating value=rating(agency,id);EvaluationProceeding p=proceeding(agency,value.getProceedingId());version(value.getVersion(),r.recordVersion());switch(action){case"submit"->{requireAssigned(p,value.getStageId(),actor,EvaluationAssignment.Role.PANEL_MEMBER);requireClearance(p,candidate(agency,p,value.getCandidateId()),actor);value.submit(actor,Instant.now());}case"return"->{requireCoordinator(p,actor);value.returnForCorrection(actor,r.reason(),Instant.now());}default->throw new IllegalArgumentException("Rating action is invalid");}value=ratings.saveAndFlush(value);p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,action.toUpperCase(Locale.ROOT)+"_PANEL_RATING","RSP_PANEL_RATING",id,value.getRatingRevision(),value.getVersion(),null,response(value),r.reason(),correlation);return response(value);}

 @Override public ReferenceResponse reference(String agency,String proceedingId,ReferenceInput r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,proceedingId);requireAssigned(p,r.stageId(),actor,EvaluationAssignment.Role.REFERENCE_CHECKER);EvaluationCandidate candidate=candidate(agency,p,r.candidateId());requireClearance(p,candidate,actor);EvaluationStage stage=stage(p,r.stageId());if(stage.getType()!=EvaluationStage.Type.BACKGROUND_REFERENCE_CHECK)throw new ApplicationConflictException("The stage is not a background/reference check");if(references.findByAgencyIdAndProceedingIdAndCandidateIdAndStageIdAndCheckTypeIgnoreCase(agency,p.getId(),candidate.getId(),stage.getId(),r.checkType()).isPresent())throw new ApplicationConflictException("This reference check already exists");ReferenceCheck value=references.saveAndFlush(new ReferenceCheck(agency,p.getId(),candidate.getId(),stage.getId(),r.checkType(),r.sourceCategory(),r.lawfulBasisReference(),actor,Instant.now()));startAssessment(p);audit.record(agency,"CREATE_REFERENCE_CHECK","RSP_REFERENCE_CHECK",value.getId(),null,value.getVersion(),null,response(value),null,correlation);return response(value);}
 @Override public ReferenceResponse completeReference(String agency,String id,CompleteReference r,String actor,String correlation){ReferenceCheck value=reference(agency,id);EvaluationProceeding p=proceeding(agency,value.getProceedingId());version(value.getVersion(),r.recordVersion());requireAssigned(p,value.getStageId(),actor,EvaluationAssignment.Role.REFERENCE_CHECKER);requireClearance(p,candidate(agency,p,value.getCandidateId()),actor);value.complete(r.outcome(),r.applicantSafeText(),r.confidentialNotes(),actor,Instant.now());value=references.saveAndFlush(value);p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"COMPLETE_REFERENCE_CHECK","RSP_REFERENCE_CHECK",id,null,value.getVersion(),null,response(value),r.confidentialNotes(),correlation);return response(value);}
 @Override public ReferenceResponse validateReference(String agency,String id,Transition r,String actor,String correlation){ReferenceCheck value=reference(agency,id);EvaluationProceeding p=proceeding(agency,value.getProceedingId());version(value.getVersion(),r.recordVersion());requireAssigned(p,value.getStageId(),actor,EvaluationAssignment.Role.VALIDATOR);requireClearance(p,candidate(agency,p,value.getCandidateId()),actor);value.validate(actor,Instant.now());value=references.saveAndFlush(value);p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"VALIDATE_REFERENCE_CHECK","RSP_REFERENCE_CHECK",id,null,value.getVersion(),null,response(value),r.reason(),correlation);return response(value);}

@Override public ComparativeResponse generateComparative(String agency,String proceedingId,Transition r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,proceedingId);requireCoordinator(p,actor);version(p.getVersion(),r.recordVersion());if(p.getStatus()!=EvaluationProceeding.Status.IN_ASSESSMENT)throw new ApplicationConflictException("Comparative evaluation requires an IN_ASSESSMENT proceeding");if(comparisons.findByAgencyIdAndProceedingIdAndStatus(agency,p.getId(),ComparativeEvaluation.Status.FINALIZED).isPresent())throw new ApplicationConflictException("A finalized comparative evaluation already exists");List<EvaluationStage> configured=stages.findByAgencyIdAndPolicyIdOrderByDisplayOrderAsc(agency,p.getBinding().getPolicy().getId());List<CalculatedCandidate> calculated=new ArrayList<>();for(EvaluationCandidate candidate:candidates.findByAgencyIdAndProceedingIdOrderByAdmittedAtAsc(agency,p.getId()))calculated.add(calculate(p,candidate,configured));assignRanks(calculated,p.getBinding().getPolicy().getTieRule());Map<String,Object> snapshot=new LinkedHashMap<>();snapshot.put("proceedingId",p.getId());snapshot.put("policyId",p.getBinding().getPolicy().getId());snapshot.put("policyDefinitionVersion",p.getBinding().getPolicy().getDefinitionVersion());snapshot.put("policyFingerprint",p.getPolicyFingerprint());snapshot.put("roundingScale",p.getBinding().getPolicy().getRoundingScale());snapshot.put("roundingMode",p.getBinding().getPolicy().getRoundingMode());snapshot.put("tieRule",p.getBinding().getPolicy().getTieRule());snapshot.put("candidates",calculated.stream().map(c->{Map<String,Object> value=new LinkedHashMap<>();value.put("candidateId",c.candidateId());value.put("totalScore",c.totalScore());value.put("rankNumber",c.rankNumber());value.put("tieGroup",c.tieGroup());value.put("excluded",c.excluded());value.put("exclusionReason",c.exclusionReason());value.put("stages",c.stages());return value;}).toList());String serialized=json(snapshot);String fingerprint=sha256(serialized.getBytes(StandardCharsets.UTF_8));int revision=Math.toIntExact(comparisons.countByAgencyIdAndProceedingId(agency,p.getId())+1);ComparativeEvaluation value=comparisons.saveAndFlush(new ComparativeEvaluation(agency,p.getId(),revision,null,p.getBinding().getPolicy().getId(),p.getBinding().getPolicy().getDefinitionVersion(),p.getPolicyFingerprint(),serialized,fingerprint,actor,Instant.now()));String evaluationId=value.getId();List<ComparativeEvaluationItem> items=calculated.stream().map(c->new ComparativeEvaluationItem(agency,evaluationId,c.candidateId(),c.totalScore(),c.rankNumber(),c.tieGroup(),json(c.stages()),c.excluded(),c.exclusionReason())).toList();comparisonItems.saveAll(items);value.finalizeEvaluation(actor,Instant.now());value=comparisons.saveAndFlush(value);p.beginDeliberation();p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"FINALIZE_COMPARATIVE_EVALUATION","RSP_COMPARATIVE_EVALUATION",value.getId(),revision,value.getVersion(),null,response(value),r.reason(),correlation);return response(value);}
 @Override public MeetingResponse createMeeting(String agency,String proceedingId,MeetingInput r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,proceedingId);requireCoordinator(p,actor);if(p.getStatus()!=EvaluationProceeding.Status.FOR_DELIBERATION)throw new ApplicationConflictException("A meeting requires a proceeding ready for deliberation");if(comparisons.findByAgencyIdAndProceedingIdAndStatus(agency,p.getId(),ComparativeEvaluation.Status.FINALIZED).isEmpty())throw new ApplicationConflictException("A finalized comparative evaluation is required");int revision=Math.toIntExact(meetings.countByAgencyIdAndProceedingId(agency,p.getId())+1);HrmpsbMeeting value=meetings.saveAndFlush(new HrmpsbMeeting(agency,p.getId(),revision,r.scheduledAt(),r.timeZone(),r.venue(),r.agenda(),r.quorumRequired()));if(r.minutes()!=null)value.update(r.scheduledAt(),r.timeZone(),r.venue(),r.agenda(),r.quorumRequired(),r.minutes());value=meetings.saveAndFlush(value);p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"CREATE_HRMPSB_MEETING","RSP_HRMPSB_MEETING",value.getId(),revision,value.getVersion(),null,response(value),null,correlation);return response(value);}
 @Override public MeetingResponse updateMeeting(String agency,String id,MeetingInput r,String actor,String correlation){HrmpsbMeeting value=meeting(agency,id);EvaluationProceeding p=proceeding(agency,value.getProceedingId());requireCoordinator(p,actor);version(value.getVersion(),r.recordVersion());value.update(r.scheduledAt(),r.timeZone(),r.venue(),r.agenda(),r.quorumRequired(),r.minutes());value=meetings.saveAndFlush(value);p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"UPDATE_HRMPSB_MEETING","RSP_HRMPSB_MEETING",id,value.getMeetingRevision(),value.getVersion(),null,response(value),null,correlation);return response(value);}
 @Override public MeetingResponse transitionMeeting(String agency,String id,Transition r,String actor,String action,String correlation){HrmpsbMeeting value=meeting(agency,id);EvaluationProceeding p=proceeding(agency,value.getProceedingId());requireCoordinator(p,actor);version(value.getVersion(),r.recordVersion());boolean finalize=false;switch(action){case"schedule"->value.schedule();case"begin"->value.begin();case"finalize"->{if(attendance.countByAgencyIdAndMeetingIdAndStatusAndVotingEligibleTrue(agency,id,HrmpsbAttendance.Status.PRESENT)<value.getQuorumRequired())throw new ApplicationConflictException("The HRMPSB quorum is not met");long expected=candidates.findByAgencyIdAndProceedingIdOrderByAdmittedAtAsc(agency,p.getId()).stream().filter(c->c.getApplication().getStatus()!=PositionApplication.Status.WITHDRAWN).count();if(resolutions.countByAgencyIdAndMeetingId(agency,id)!=expected)throw new ApplicationConflictException("Every active candidate requires an HRMPSB resolution");value.finalizeMeeting(actor,r.reason(),Instant.now());finalize=true;}default->throw new IllegalArgumentException("Meeting action is invalid");}value=meetings.saveAndFlush(value);p.executionChanged();if(finalize)p.finalizeProceeding();proceedings.saveAndFlush(p);audit.record(agency,action.toUpperCase(Locale.ROOT)+"_HRMPSB_MEETING","RSP_HRMPSB_MEETING",id,value.getMeetingRevision(),value.getVersion(),null,response(value),r.reason(),correlation);return response(value);}
 @Override public MeetingResponse attendance(String agency,String meetingId,MeetingAttendance r,String actor,String correlation){HrmpsbMeeting value=meeting(agency,meetingId);EvaluationProceeding p=proceeding(agency,value.getProceedingId());requireCoordinator(p,actor);if(value.getStatus()==HrmpsbMeeting.Status.FINALIZED)throw new ApplicationConflictException("Finalized attendance is immutable");CommitteeMember member=requireCommitteeMember(p,r.employeeNo());boolean voter=member.voting()&&r.status()==HrmpsbAttendance.Status.PRESENT;HrmpsbAttendance record=attendance.findByAgencyIdAndMeetingIdAndEmployeeNoIgnoreCase(agency,meetingId,r.employeeNo()).orElse(null);if(record!=null)throw new ApplicationConflictException("Attendance has already been recorded; use a successor meeting to correct finalized evidence");attendance.saveAndFlush(new HrmpsbAttendance(agency,meetingId,r.employeeNo(),member.getRole().name(),r.status(),voter,actor,Instant.now(),r.remarks()));p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"RECORD_HRMPSB_ATTENDANCE","RSP_HRMPSB_MEETING",meetingId,value.getMeetingRevision(),value.getVersion(),null,Map.of("employeeNo",r.employeeNo(),"status",r.status().name()),r.remarks(),correlation);return response(value);}
 @Override public MeetingResponse resolution(String agency,String meetingId,ResolutionInput r,String actor,String correlation){HrmpsbMeeting value=meeting(agency,meetingId);EvaluationProceeding p=proceeding(agency,value.getProceedingId());requireCoordinator(p,actor);if(value.getStatus()!=HrmpsbMeeting.Status.IN_DELIBERATION)throw new ApplicationConflictException("Resolutions are recorded only during deliberation");EvaluationCandidate candidate=candidate(agency,p,r.candidateId());requireActive(candidate);if(resolutions.findByAgencyIdAndMeetingIdAndCandidateId(agency,meetingId,candidate.getId()).isPresent())throw new ApplicationConflictException("This candidate already has a meeting resolution");int eligible=Math.toIntExact(attendance.countByAgencyIdAndMeetingIdAndStatusAndVotingEligibleTrue(agency,meetingId,HrmpsbAttendance.Status.PRESENT));if(r.method()==HrmpsbResolution.Method.VOTE&&r.votesFor()+r.votesAgainst()+r.abstentions()>eligible)throw new ApplicationConflictException("Vote counts exceed eligible attendance");HrmpsbResolution resolution=resolutions.saveAndFlush(new HrmpsbResolution(agency,meetingId,candidate.getId(),r.recommendation(),r.reason(),r.method(),r.votesFor(),r.votesAgainst(),r.abstentions(),actor,Instant.now()));p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"RECORD_HRMPSB_RESOLUTION","RSP_HRMPSB_RESOLUTION",resolution.getId(),null,resolution.getVersion(),null,Map.of("candidateId",candidate.getId(),"recommendation",r.recommendation().name()),r.reason(),correlation);return response(value);}

 @Override public EvidenceResponse uploadEvidence(String agency,String proceedingId,String candidateId,String ownerType,String ownerId,String classification,String retention,MultipartFile file,String actor,String correlation){EvaluationProceeding p=proceeding(agency,proceedingId);requireCommitteeMember(p,actor);EvaluationEvidence.OwnerType type=parse(EvaluationEvidence.OwnerType.class,ownerType,"ownerType");EvaluationEvidence.Classification security=parse(EvaluationEvidence.Classification.class,classification,"classification");String candidate=candidateId==null||candidateId.isBlank()?null:candidate(agency,p,candidateId).getId();requireEvidenceOwner(agency,p,type,ownerId,candidate);if(!properties.storage().enabled())throw new IllegalStateException("Evaluation evidence storage is disabled");if(file==null||file.isEmpty()||file.getSize()>properties.storage().maximumBytes())throw new IllegalArgumentException("Evidence size is invalid");String media=Objects.requireNonNullElse(file.getContentType(),"");if(!properties.storage().allowedMediaTypes().contains(media))throw new IllegalArgumentException("Evidence media type is not allowed");byte[] bytes;try{bytes=file.getBytes();}catch(IOException e){throw new IllegalArgumentException("Evidence could not be read",e);}verifySignature(media,bytes);String filename=safeFilename(file.getOriginalFilename());String key=agency+"/evaluation/"+p.getId()+"/"+UUID.randomUUID().toString().replace("-","");storage.put(key,bytes,media);try{EvaluationEvidence value=evidence.saveAndFlush(new EvaluationEvidence(agency,p.getId(),candidate,type,ownerId,security,filename,media,bytes.length,sha256(bytes),storage.provider(),key,retention,actor,Instant.now()));p.executionChanged();proceedings.saveAndFlush(p);audit.record(agency,"UPLOAD_EVALUATION_EVIDENCE","RSP_EVALUATION_EVIDENCE",value.getId(),null,value.getVersion(),null,Map.of("ownerType",type.name(),"ownerId",ownerId,"checksum",value.getChecksum(),"size",value.getByteSize()),null,correlation);return response(value);}catch(RuntimeException e){storage.delete(key);throw e;}}
 @Override @Transactional(readOnly=true)public byte[] evidence(String agency,String id,String actor){EvaluationEvidence value=evidence.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Evaluation evidence was not found"));requireCommitteeMember(proceeding(agency,value.getProceedingId()),actor);try(InputStream in=storage.get(value.getStorageObjectKey())){return in.readAllBytes();}catch(IOException e){throw new IllegalStateException("Evaluation evidence could not be read",e);}}
 @Override @Transactional(readOnly=true)public ApplicantEvaluationStatus applicantStatus(String agency,String applicant,String application){EvaluationCandidate candidate=candidates.findByAgencyIdAndApplicationId(agency,application).orElseThrow(()->new ResourceNotFoundException("No evaluation exists for this application"));if(!candidate.getApplicantId().equals(applicant))throw new AccessDeniedException("Applicants may read only their own evaluation schedule");EvaluationProceeding p=candidate.getProceeding();String progress=switch(p.getStatus()){case DRAFT,OPEN->"ASSESSMENT SCHEDULED";case IN_ASSESSMENT->"ASSESSMENT IN PROGRESS";case FOR_DELIBERATION,FINALIZED->"ASSESSMENT COMPLETED";case CANCELLED->"ASSESSMENT CANCELLED";};List<ApplicantSchedule> safe=new ArrayList<>();for(EvaluationSessionCandidate link:sessionCandidates.findByAgencyIdAndCandidateId(agency,candidate.getId())){EvaluationSession session=session(agency,link.getSessionId());if(session.getStatus()==EvaluationSession.Status.DRAFT)continue;EvaluationStage stage=stages.findById(session.getStageId()).orElseThrow();safe.add(new ApplicantSchedule(session.getId(),stage.getName(),session.getStartsAt(),session.getEndsAt(),session.getTimeZone(),session.getDeliveryMode().name(),session.getVenue(),link.getInvitationStatus().name(),link.getAttendanceStatus().name()));}safe.sort(Comparator.comparing(ApplicantSchedule::startsAt));return new ApplicantEvaluationStatus(application,progress,safe);}

 private CalculatedCandidate calculate(EvaluationProceeding p,EvaluationCandidate candidate,List<EvaluationStage> configured){boolean excluded=candidate.getApplication().getStatus()==PositionApplication.Status.WITHDRAWN;String exclusion=excluded?"APPLICANT_WITHDRAWN":null;BigDecimal total=BigDecimal.ZERO;List<StageCalculation> breakdown=new ArrayList<>();for(EvaluationStage stage:configured){BigDecimal score=null;String gate=null;if(isPanel(stage)){List<PanelRating> submitted=ratings.findByAgencyIdAndProceedingIdAndCandidateIdAndStageIdAndStatus(p.getAgencyId(),p.getId(),candidate.getId(),stage.getId(),PanelRating.Status.SUBMITTED);if(submitted.size()<stage.getMinimumRaters())throw new ApplicationConflictException("Candidate "+candidate.getId()+" is missing the minimum independent ratings for "+stage.getCode());score=submitted.stream().map(PanelRating::getNormalizedScore).reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(submitted.size()),p.getBinding().getPolicy().getRoundingScale(),rounding(p));}else{StageResult result=results.findByAgencyIdAndProceedingIdAndCandidateIdAndStageIdAndCurrentResultKeyIsNotNull(p.getAgencyId(),p.getId(),candidate.getId(),stage.getId()).orElse(null);if(stage.getMode()!=EvaluationStage.Mode.INFORMATIONAL&&(result==null||result.getStatus()!=StageResult.Status.VALIDATED))throw new ApplicationConflictException("Candidate "+candidate.getId()+" has an incomplete validated result for "+stage.getCode());if(result!=null&&result.getStatus()==StageResult.Status.VALIDATED){score=result.getNormalizedScore();gate=result.getGateOutcome()==null?null:result.getGateOutcome().name();if(result.getGateOutcome()==StageResult.GateOutcome.FAIL){excluded=true;exclusion="FAILED_GATE:"+stage.getCode();}}}BigDecimal contribution=BigDecimal.ZERO;if(stage.getMode()==EvaluationStage.Mode.SCORED){if(score==null)throw new ApplicationConflictException("Missing scored result is not treated as zero");contribution=score.multiply(stage.getWeight()).divide(new BigDecimal("100"),p.getBinding().getPolicy().getRoundingScale(),rounding(p));total=total.add(contribution);}breakdown.add(new StageCalculation(stage.getId(),stage.getCode(),stage.getMode().name(),score,gate,stage.getWeight(),contribution));}total=total.setScale(p.getBinding().getPolicy().getRoundingScale(),rounding(p));return new CalculatedCandidate(candidate.getId(),total,0,0,excluded,exclusion,breakdown);}
 static void assignRanks(List<CalculatedCandidate> values,EvaluationPolicy.TieRule rule){List<CalculatedCandidate> ordered=values.stream().filter(v->!v.excluded()).sorted(Comparator.comparing(CalculatedCandidate::totalScore).reversed().thenComparing(CalculatedCandidate::candidateId)).toList();BigDecimal prior=null;int dense=0;for(int i=0;i<ordered.size();i++){CalculatedCandidate value=ordered.get(i);if(prior==null||value.totalScore().compareTo(prior)!=0)dense++;int rank=rule==EvaluationPolicy.TieRule.COMPETITION?(prior==null||value.totalScore().compareTo(prior)!=0?i+1:ordered.get(i-1).rankNumber()):dense;value.rankNumber(rank);value.tieGroup(dense);prior=value.totalScore();}int excludedRank=Math.max(1,ordered.size()+1);for(CalculatedCandidate value:values)if(value.excluded()){value.rankNumber(excludedRank);value.tieGroup(excludedRank);}}

 private EvaluationProceeding proceeding(String agency,String id){return proceedings.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Evaluation proceeding was not found"));}
 private EvaluationCandidate candidate(String agency,EvaluationProceeding proceeding,String id){EvaluationCandidate value=candidates.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Evaluation candidate was not found"));if(!value.getProceeding().getId().equals(proceeding.getId()))throw new ResourceNotFoundException("Evaluation candidate was not found");return value;}
 private EvaluationStage stage(EvaluationProceeding proceeding,String id){EvaluationStage value=stages.findById(id).orElseThrow(()->new ResourceNotFoundException("Evaluation stage was not found"));if(!value.getAgencyId().equals(proceeding.getAgencyId())||!value.getPolicyId().equals(proceeding.getBinding().getPolicy().getId()))throw new ResourceNotFoundException("Evaluation stage was not found");return value;}
 private EvaluationSession session(String agency,String id){return sessions.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Evaluation session was not found"));}
 private StageResult result(String agency,String id){return results.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Evaluation result was not found"));}
 private PanelRating rating(String agency,String id){return ratings.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Panel rating was not found"));}
 private ReferenceCheck reference(String agency,String id){return references.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Reference check was not found"));}
 private HrmpsbMeeting meeting(String agency,String id){return meetings.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("HRMPSB meeting was not found"));}
 private void requireCoordinator(EvaluationProceeding proceeding,String actor){CommitteeMember member=requireCommitteeMember(proceeding,actor);if(member.getRole()!=CommitteeMember.Role.CHAIRPERSON&&member.getRole()!=CommitteeMember.Role.SECRETARIAT)throw new AccessDeniedException("Only the HRMPSB chairperson or secretariat may coordinate this action");}
 private CommitteeMember requireCommitteeMember(EvaluationProceeding proceeding,String employee){return members.findEffective(proceeding.getAgencyId(),proceeding.getCommittee().getId(),employee,proceeding.getPlannedAsOfDate()).orElseThrow(()->new AccessDeniedException("An effective HRMPSB membership is required"));}
 private void requireAssigned(EvaluationProceeding proceeding,String stageId,String actor,EvaluationAssignment.Role role){boolean assigned=assignments.existsByAgencyIdAndProceedingIdAndStageIdAndEmployeeNoIgnoreCaseAndRoleAndActiveTrue(proceeding.getAgencyId(),proceeding.getId(),stageId,actor,role)||assignments.existsByAgencyIdAndProceedingIdAndEmployeeNoIgnoreCaseAndRoleAndActiveTrue(proceeding.getAgencyId(),proceeding.getId(),actor,role);if(!assigned)throw new AccessDeniedException("An active "+role+" assignment is required");}
 private void requireClearance(EvaluationProceeding proceeding,EvaluationCandidate candidate,String actor){ConflictDeclaration conflict=conflicts.findByAgencyIdAndProceedingIdAndCandidateIdAndEmployeeNoIgnoreCase(proceeding.getAgencyId(),proceeding.getId(),candidate.getId(),actor).orElse(null);if(conflict!=null&&conflict.blocksAction())throw new AccessDeniedException("A conflict declaration prevents action for this candidate");}
 private static void requireExecutionState(EvaluationProceeding proceeding){if(proceeding.getStatus()!=EvaluationProceeding.Status.OPEN&&proceeding.getStatus()!=EvaluationProceeding.Status.IN_ASSESSMENT)throw new ApplicationConflictException("The proceeding is not open for assessment execution");}
 private static void requireActive(EvaluationCandidate candidate){if(candidate.getStatus()!=EvaluationCandidate.Status.ADMITTED||candidate.getApplication().getStatus()==PositionApplication.Status.WITHDRAWN)throw new ApplicationConflictException("The candidate is not active in this proceeding");}
 private void startAssessment(EvaluationProceeding proceeding){if(proceeding.getStatus()==EvaluationProceeding.Status.OPEN)proceeding.beginAssessment();requireExecutionState(proceeding);proceeding.executionChanged();proceedings.saveAndFlush(proceeding);}
 private static void version(long actual,Long expected){if(expected==null)throw new IllegalArgumentException("recordVersion is required");if(actual!=expected)throw new ApplicationConflictException("The record was changed by another user");}
 private static void validateAssignmentRole(CommitteeMember member,AssignmentInput input){if(input.role()==EvaluationAssignment.Role.PANEL_MEMBER&&!member.voting())throw new ApplicationConflictException("Only a voting HRMPSB member may be assigned as a panel member");if(input.role()==EvaluationAssignment.Role.ALTERNATE&&member.getRole()!=CommitteeMember.Role.ALTERNATE)throw new ApplicationConflictException("An alternate assignment requires an alternate committee member");if(input.role()!=EvaluationAssignment.Role.ALTERNATE&&input.alternateForEmployeeNo()!=null)throw new IllegalArgumentException("alternateForEmployeeNo is valid only for an alternate assignment");}
 private static boolean hasRole(List<AssignmentInput> values,AssignmentInput source,EvaluationAssignment.Role role){return values.stream().anyMatch(value->value!=source&&value.role()==role&&value.employeeNo().equalsIgnoreCase(source.employeeNo())&&Objects.equals(value.stageId(),source.stageId())&&Objects.equals(value.candidateId(),source.candidateId()));}
 private static boolean isPanel(EvaluationStage stage){return stage.getType()==EvaluationStage.Type.COMPETENCY_BASED_INTERVIEW||stage.getType()==EvaluationStage.Type.BEHAVIORAL_EVENT_INTERVIEW;}
 private static RoundingMode rounding(EvaluationProceeding proceeding){return switch(proceeding.getBinding().getPolicy().getRoundingMode()){case HALF_UP->RoundingMode.HALF_UP;case HALF_EVEN->RoundingMode.HALF_EVEN;case DOWN->RoundingMode.DOWN;};}

 private void requireEvidenceOwner(String agency,EvaluationProceeding proceeding,EvaluationEvidence.OwnerType type,String owner,String candidate){switch(type){case STAGE_RESULT->{StageResult value=result(agency,owner);if(!value.getProceedingId().equals(proceeding.getId())||candidate!=null&&!candidate.equals(value.getCandidateId()))throw new ResourceNotFoundException("Evidence owner was not found");}case PANEL_RATING->{PanelRating value=rating(agency,owner);if(!value.getProceedingId().equals(proceeding.getId())||candidate!=null&&!candidate.equals(value.getCandidateId()))throw new ResourceNotFoundException("Evidence owner was not found");}case REFERENCE_CHECK->{ReferenceCheck value=reference(agency,owner);if(!value.getProceedingId().equals(proceeding.getId())||candidate!=null&&!candidate.equals(value.getCandidateId()))throw new ResourceNotFoundException("Evidence owner was not found");}case MEETING->{HrmpsbMeeting value=meeting(agency,owner);if(!value.getProceedingId().equals(proceeding.getId()))throw new ResourceNotFoundException("Evidence owner was not found");}case RESOLUTION->{HrmpsbResolution value=resolutions.findByIdAndAgencyId(owner,agency).orElseThrow(()->new ResourceNotFoundException("Evidence owner was not found"));HrmpsbMeeting meeting=meeting(agency,value.getMeetingId());if(!meeting.getProceedingId().equals(proceeding.getId())||candidate!=null&&!candidate.equals(value.getCandidateId()))throw new ResourceNotFoundException("Evidence owner was not found");}}}
 private static void verifySignature(String media,byte[] bytes){boolean valid=switch(media){case"application/pdf"->bytes.length>=4&&bytes[0]=='%'&&bytes[1]=='P'&&bytes[2]=='D'&&bytes[3]=='F';case"image/png"->bytes.length>=8&&(bytes[0]&255)==137&&bytes[1]=='P'&&bytes[2]=='N'&&bytes[3]=='G';case"image/jpeg"->bytes.length>=3&&(bytes[0]&255)==255&&(bytes[1]&255)==216&&(bytes[2]&255)==255;default->false;};if(!valid)throw new IllegalArgumentException("Evidence content does not match its media type");}
 private static String safeFilename(String value){String filename=Objects.requireNonNullElse(value,"evidence").replace('\\','/');filename=filename.substring(filename.lastIndexOf('/')+1).replaceAll("[^A-Za-z0-9._ -]","_").trim();if(filename.isBlank()||filename.equals(".")||filename.equals(".."))return "evidence";return filename.length()>255?filename.substring(filename.length()-255):filename;}
 private static String sha256(byte[] bytes){try{byte[] digest=MessageDigest.getInstance("SHA-256").digest(bytes);return java.util.HexFormat.of().formatHex(digest);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private static <E extends Enum<E>>E parse(Class<E> type,String value,String field){if(value==null)throw new IllegalArgumentException(field+" is required");try{return Enum.valueOf(type,value.trim().toUpperCase(Locale.ROOT));}catch(IllegalArgumentException e){throw new IllegalArgumentException(field+" is invalid");}}
 private String json(Object value){try{return json.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalStateException("Evaluation snapshot could not be serialized",e);}}

 private SessionResponse response(EvaluationSession value){List<SessionCandidateResponse> links=sessionCandidates.findByAgencyIdAndSessionId(value.getAgencyId(),value.getId()).stream().map(link->new SessionCandidateResponse(link.getId(),link.getCandidateId(),link.getInvitationStatus().name(),link.getAttendanceStatus().name(),link.getVersion())).toList();return new SessionResponse(value.getId(),value.getProceedingId(),value.getStageId(),value.getSessionRevision(),value.getStatus().name(),value.getStartsAt(),value.getEndsAt(),value.getTimeZone(),value.getDeliveryMode().name(),value.getVenue(),value.getInstructions(),value.getCapacity(),value.getResponsibleEmployeeNo(),value.getChangeReason(),value.getVersion(),links);}
 private AssignmentResponse response(EvaluationAssignment value){return new AssignmentResponse(value.getId(),value.getStageId(),value.getCandidateId(),value.getEmployeeNo(),value.getRole().name(),value.isActive(),value.getAlternateForEmployeeNo(),value.getVersion());}
 private ConflictResponse response(ConflictDeclaration value){return new ConflictResponse(value.getId(),value.getProceedingId(),value.getCandidateId(),value.getEmployeeNo(),value.getOutcome().name(),value.getResolvedOutcome()==null?null:value.getResolvedOutcome().name(),value.getDeclaration(),value.getVersion());}
 private StageResultResponse response(StageResult value){return new StageResultResponse(value.getId(),value.getProceedingId(),value.getSessionId(),value.getCandidateId(),value.getStageId(),value.getResultRevision(),value.getStatus().name(),value.getRawScore(),value.getMaximumScore(),value.getNormalizedScore(),value.getGateOutcome()==null?null:value.getGateOutcome().name(),value.getRemarks(),value.getRecordedBy(),value.getSubmittedBy(),value.getValidatedBy(),value.getReturnReason(),value.getVersion());}
 private RatingResponse response(PanelRating value){List<RatingItemResponse> items=ratingItems.findByAgencyIdAndRatingId(value.getAgencyId(),value.getId()).stream().map(item->new RatingItemResponse(item.getCriterionId(),item.getRawScore(),item.getMaximumScore(),item.getNormalizedScore(),item.getWeightedScore(),item.getRemarks())).toList();return new RatingResponse(value.getId(),value.getProceedingId(),value.getCandidateId(),value.getStageId(),value.getRaterEmployeeNo(),value.getRatingRevision(),value.getStatus().name(),value.getNormalizedScore(),value.getOverallRemarks(),value.getReturnReason(),value.getVersion(),items);}
 private ReferenceResponse response(ReferenceCheck value){return new ReferenceResponse(value.getId(),value.getProceedingId(),value.getCandidateId(),value.getStageId(),value.getCheckType(),value.getSourceCategory(),value.getLawfulBasisReference(),value.getCheckerEmployeeNo(),value.getOutcome().name(),value.getStatus().name(),value.getApplicantSafeText(),value.getConfidentialNotes(),value.getValidatedBy(),value.getVersion());}
 private MeetingResponse response(HrmpsbMeeting value){return new MeetingResponse(value.getId(),value.getProceedingId(),value.getMeetingRevision(),value.getStatus().name(),value.getScheduledAt(),value.getTimeZone(),value.getVenue(),value.getAgenda(),value.getMinutes(),value.getQuorumRequired(),value.getFinalizedBy(),value.getFinalizedAt(),value.getVersion());}
 private ComparativeResponse response(ComparativeEvaluation value){List<ComparativeItemResponse> items=comparisonItems.findByAgencyIdAndComparativeEvaluationIdOrderByRankNumberAsc(value.getAgencyId(),value.getId()).stream().map(item->new ComparativeItemResponse(item.getCandidateId(),item.getTotalScore(),item.getRankNumber(),item.getTieGroup(),item.getStageBreakdown(),item.isExcluded(),item.getExclusionReason())).toList();return new ComparativeResponse(value.getId(),value.getProceedingId(),value.getEvaluationRevision(),value.getStatus().name(),value.getPolicyId(),value.getPolicyDefinitionVersion(),value.getPolicyFingerprint(),value.getCalculationFingerprint(),value.getGeneratedBy(),value.getGeneratedAt(),value.getFinalizedBy(),value.getFinalizedAt(),value.getVersion(),items);}
 private static EvidenceResponse response(EvaluationEvidence value){return new EvidenceResponse(value.getId(),value.getProceedingId(),value.getCandidateId(),value.getOwnerType().name(),value.getOwnerId(),value.getClassification().name(),value.getOriginalFilename(),value.getMediaType(),value.getByteSize(),value.getChecksum(),value.getRetentionTag(),value.getVersion());}

 record StageCalculation(String stageId,String stageCode,String mode,BigDecimal score,String gateOutcome,BigDecimal weight,BigDecimal contribution){}
 static final class CalculatedCandidate{private final String candidateId;private final BigDecimal totalScore;private int rankNumber;private int tieGroup;private final boolean excluded;private final String exclusionReason;private final List<StageCalculation> stages;CalculatedCandidate(String candidateId,BigDecimal totalScore,int rankNumber,int tieGroup,boolean excluded,String exclusionReason,List<StageCalculation> stages){this.candidateId=candidateId;this.totalScore=totalScore;this.rankNumber=rankNumber;this.tieGroup=tieGroup;this.excluded=excluded;this.exclusionReason=exclusionReason;this.stages=List.copyOf(stages);}public String candidateId(){return candidateId;}public BigDecimal totalScore(){return totalScore;}public int rankNumber(){return rankNumber;}public void rankNumber(int value){rankNumber=value;}public int tieGroup(){return tieGroup;}public void tieGroup(int value){tieGroup=value;}public boolean excluded(){return excluded;}public String exclusionReason(){return exclusionReason;}public List<StageCalculation> stages(){return stages;}}
}
